import{_ as i,l as E,o as e,c as o,v as t,p as s,x as l,d as n,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"EUV 层数与节点","description":"","frontmatter":{"title":"EUV 层数与节点","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-layers-per-node.md","filePath":"litho/euv-layers-per-node.md","lastUpdated":1789023840000}'),d={name:"litho/euv-layers-per-node.md"};function A(_,a,V,c,m,B){const r=E("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="euv-层数与节点" tabindex="-1">EUV 层数与节点 <a class="header-anchor" href="#euv-层数与节点" aria-label="Permalink to &quot;EUV 层数与节点&quot;">​</a></h1><div class="epigraph"><p>节点推进不是「所有层都改 EUV」。切金属、通孔、心轴这些 $k_1$ 最紧的层先上，其余仍可以浸没多重图形。</p><footer>—— 对照 ASML / 晶圆厂对 EUV 层插入的公开叙事；不要编造某代具体层数表</footer></div><p><a href="/litho/high-na-pattern-transfer">上一课</a>把单层薄胶做成可转印。缺口是整节点：多少层值得付 EUV 的掩模、源和随机税，多少层留在 ArF 浸没。单次曝光还能走到多小的 \\(k_1\\)，留给[下一课](/litho/euv-single-expose-limit）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>转印课默认「这一层已经决定用 EUV」。工厂的问题是层清单。7 nm 级公开叙事是少量关键层 EUV 替换四重浸没；5/3 nm 级层数增加；High-NA 针对更紧的金属间距，而不是把植入层也改波长。每加一层 EUV：掩模成本、pellicle、源功率、随机缺陷、真空污染都进 COGS。能用浸没 SADP/LELE 且良率可接受的层，不一定要换。</p><p>缺口是插入策略，不是再写一次薄胶栈。互补式 EUV 与浸没混用，在主干课已出现；本课钉「层数随节点涨，但不是全 EUV 厂」。</p><p><span class="marginnote">不要把某次财报或技术日上的层数抄成物理定律。本课只保留公开逻辑：关键切层先上、层数随节距涨、High-NA 替换最紧的那几层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层决策：节距与 \\(k_1\\)、套刻、缺陷、掩模张数（EUV 单次 vs 浸没多次）、产能。孔阵列往往因随机缺失对 EUV 剂量和胶更苛刻，可能晚于线层或走不同胶。金属层方向性设计规则与偶极照明绑定，层数增加等于 SMO/掩模库膨胀。</p><p>与转印：EUV 层薄胶栈的轨道和刻蚀模块要按层别复制，不是全厂一条胶。混用节点的套刻网格必须同时服务 0.33 EUV、High-NA 半场和浸没。</p><h3 id="掩模张数是隐藏的层数" tabindex="-1">掩模张数是隐藏的层数 <a class="header-anchor" href="#掩模张数是隐藏的层数" aria-label="Permalink to &quot;掩模张数是隐藏的层数&quot;">​</a></h3><p>浸没多重把一层器件变成两张、四张版；EUV 单次把张数压回去，但 pellicle、光化检验和空白缺陷率把单张成本抬高。层数决策是「器件层」与「掩模张数」两本账。只数 EUV 曝光次数会低估浸没多重的扫描机占用，只数工具台数会低估 EUV 掩模周期。</p>',12)),(e(),s(p,null,{default:l(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20K1%5B%22%E6%9C%80%E7%B4%A7%20k1%20%E5%B1%82%22%5D%20--%3E%20EUV%5B%22EUV%20%E5%8D%95%E6%AC%A1%22%5D%0A%20%20LOOSE%5B%22%E8%BE%83%E6%9D%BE%E5%B1%82%22%5D%20--%3E%20IMM%5B%22%E6%B5%B8%E6%B2%A1%20%2F%20%E5%A4%9A%E9%87%8D%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20NODE%5B%22%E8%8A%82%E7%82%B9%E6%8E%A8%E8%BF%9B%22%5D%20--%3E%20MORE%5B%22EUV%20%E5%B1%82%E6%95%B0%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20HNA%5B%22High-NA%22%5D%20--%3E%20CRIT%5B%22%E6%9B%BF%E6%8D%A2%E6%9C%80%E7%B4%A7%E9%87%91%E5%B1%9E%20%2F%20%E5%AD%94%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>瑞利 \\(CD=k_1\\lambda/\\mathrm{NA}\\)。0.33 EUV 把一批原先需要 SADP 的节距收成单次；再紧则 \\(k_1\\) 掉到随机和 M3D 墙，要么多重 EUV，要么 High-NA 抬 NA。层数是这条物理墙在产品设计上的投影：标准单元金属层越多、间距越紧，EUV 版图越多。经济上，浸没多重的掩模张数和工艺步数会在某点超过单次 EUV——阈值随源功率、pellicle 和良率变，正是功率路线课的下游。</p><p><span class="marginnote">「全 EUV 节点」是营销简化。植入、厚膜、某些钝化仍可能停在 DUV。写层数时分层别，不要写一个整数打天下。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把单次曝光的 \\(k_1\\) 下限写成公式终点，下一课才写单次极限。不编造 N3/N2 的官方层数。层清单随产品系列变，同一节点的 SRAM 与逻辑金属层数不必相同。出处：ASML 节点与 EUV 层插入公开材料；Bakshi 系统经济讨论；瑞利与多重图形课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 按 \\(k_1\\) 最紧的层插入，层数随节点增加，但厂内仍是混用。</li><li>每层付掩模、源、随机和真空税；能留浸没的不必换。</li><li>下一课：单次 EUV 本身的节距墙在哪。</li><li>出处：ASML 公开节点叙事；瑞利 / 多重图形。</li></ul>',7))])}const D=i(d,[["render",A]]);export{u as __pageData,D as default};
